INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(1, 'A300601', , 'Americano Đào', 'Americano', 55000, 'Mê ly với Americano từ 100% Arabica kết hợp cùng Đào ngọt thanh, dậy vị tươi mát.', 'Đang hoạt động', NULL, '2025-04-16 21:46:16');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(2, 'A300602', , 'Americano Mơ', 'Americano', 55000, 'Mê say với Americano từ 100% Arabica kết hợp cùng Mơ chua ngọt, tươi mới mỗi ngày. *Khuấy đều để thưởng thức trọn vị', 'Dừng hoạt động', NULL, '2025-04-07 11:44:16');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(3, 'A300603', , 'Bơ Sữa Phô Mai', 'Trái cây xay', 55000, 'Bơ sáp Đắk Lắk dẻo quẹo hòa quyện lớp foam phô mai tươi mềm mịn. Thêm chút Trà Sữa Oolong Tứ Quý đượm hương càng dậy vị trái cây tươi mát. Khuấy đều để thưởng trọn vị sảng khoái.', 'Đang hoạt động', NULL, '2025-04-04 08:06:14');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(4, 'A300604', , 'Dâu Phô Mai', 'Trái Cây Xay', 55000, 'Dâu tây Đà Lạt chín mọng hòa quyện lớp foam phô mai tươi mềm mịn. Thêm chút Trà Oolong Tứ Quý đượm hương và thạch kim quất mềm tan càng dậy vị trái cây tươi mát. Khuấy đều để thưởng trọn vị sảng khoái. ', 'Đang hoạt động', NULL, '2025-04-04 08:06:29');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(5, 'A300605', , 'Bơ Arabica', 'Cà phê', 49000, 'Bơ sáp Đắk Lắk dẻo quẹo hòa quyện cùng Cà phê Arabica Cầu Đất êm mượt. Khuấy đều để thưởng thức hương vị tươi tỉnh, đầy mới lạ!', 'Đang hoạt động', NULL, '2025-04-04 07:42:06');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(6, 'A300606', , 'Bạc Xĩu', 'Cà Phê', 29000, 'Bạc xỉu chính là \"Ly sữa trắng kèm một chút cà phê\". Thức uống này rất phù hợp những ai vừa muốn trải nghiệm chút vị đắng của cà phê vừa muốn thưởng thức vị ngọt béo ngậy từ sữa.', 'Đang hoạt động', NULL, '2025-03-30 12:22:12');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(52, 'A300607', , 'Trà xanh đường đen', 'Trà xanh - Chocolate', 55000, 'Trà Xanh Đường Đen với hiệu ứng phân tầng đẹp mắt, như phác hoạ núi đồi Tây Bắc bảng lảng trong sương mây, thấp thoáng những nương chè xanh ngát. ', 'Đang hoạt động', NULL, '2025-04-05 16:18:58');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(53, 'A300608', , 'Trà vải', 'Trà trái cây', 49000, 'Chút ngọt ngào của Vải, mix cùng vị chua thanh tao từ trà hoa Hibiscus, mang đến cho bạn thức uống đúng chuẩn vừa ngon, vừa healthy.', 'Đang hoạt động', 1, '2025-03-31 09:07:11');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(54, 'A300609', , 'Ô Long Tứ Quý Dâu', 'Trà trái cây', 49000, 'Sảng khoái với vị dâu chín mọng chua thanh. Nền trà Ô Long Tứ Quý đậm hương, ngọt thanh hậu vị. Thêm tận hưởng với trân châu trắng giòn dai.', 'Đang hoạt động', 1, '2025-04-05 16:23:48');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(55, 'A300610', , 'Cà Phê Sữa Đá', 'Cà phê', 29000, 'Cà phê Đắk Lắk nguyên chất được pha phin truyền thống kết hợp với sữa đặc tạo nên hương vị đậm đà, hài hòa giữa vị ngọt đầu lưỡi và vị đắng thanh thoát nơi hậu vị.', 'Đang hoạt động', 1, '2025-04-04 08:01:07');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(56, 'A300611', , 'Bạc Xỉu Lắc Sữa Yến Mạch', 'Cà phê', 45000, 'Ngày thêm rộn ràng với Bạc Xỉu Lắc Sữa Yến Mạch. Cà phê phin Robusta đượm hương “lắc tới bến” cùng sữa yến mạch sánh mịn và đá đập mát lạnh.', 'Đang hoạt động', 1, '2025-04-05 16:19:28');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(57, 'A3006012', , 'Trà Xanh Espresso Marble', 'Trà xanh - Chocolate', 49000, 'Cho ngày thêm tươi, tỉnh, êm, mượt với Trà Xanh Espresso Marble. Đây là sự mai mối bất ngờ giữa trà xanh Tây Bắc vị mộc và cà phê Arabica Đà Lạt. ', 'Đang hoạt động', NULL, '2025-04-05 16:19:56');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(58, 'A300613', , 'Đường Đen Sữa Đá', 'Cà phê', 45000, 'Nếu chuộng vị cà phê đậm đà, bùng nổ và thích vị đường đen ngọt thơm, Đường Đen Sữa Đá đích thị là thức uống dành cho bạn. ', 'Đang hoạt động', NULL, '2025-04-05 16:19:48');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(59, 'A300614', , 'The Coffee House Sữa Đá', 'Cà phê', 39000, 'Thức uống giúp tỉnh táo tức thì để bắt đầu ngày mới thật hứng khởi. Không đắng khét như cà phê truyền thống, The Coffee House Sữa Đá mang hương vị hài hoà đầy lôi cuốn. ', 'Đang hoạt động', NULL, '2025-04-05 16:20:10');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(60, 'A300614', , 'Bạc Xỉu Nóng', 'Cà phê', 39000, 'Bạc xỉu chính là \"Ly sữa trắng kèm một chút cà phê\". Thức uống này rất phù hợp những ai vừa muốn trải nghiệm chút vị đắng của cà phê vừa muốn thưởng thức vị ngọt béo ngậy từ sữa.', 'Đang hoạt động', NULL, '2025-04-04 07:48:54');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(61, '', , 'Americano Classic', 'Americano', 39000, 'Thức uống Americano nguyên bản từ 100% Arabica, tươi tỉnh tức thì. Uống là mê!', 'Đang hoạt động', NULL, '2025-04-04 07:50:43');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(62, 'A300616', , 'Americano Quất', 'Americano', 55000, 'Mê tít với Americano từ 100% Arabica kết hợp cùng Quất chua dịu, sảng khoái tức thì. *Khuấy đều để thưởng thức trọn vị', 'Đang hoạt động', NULL, '2025-04-04 07:51:56');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(63, 'A300616', , 'Trà Sữa Oolong Tứ Quý Bơ', 'Trà sữa', 59000, 'Bơ sáp Đắk Lắk dẻo quẹo hòa quyện cùng Trà Sữa Oolong Tứ Quý đượm hương. Khó cưỡng với hương vị ngọt ngào, đậm bơ, sánh mịn. Khuấy đều để thưởng trọn vị bạn nhé!', 'Đang hoạt động', NULL, '2025-04-04 07:55:37');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(64, 'A300617', , 'Frosty Bánh Kem Dâu', 'Thức uống đá xay', 59000, 'Bồng bềnh như một đám mây, Đá Xay Frosty Bánh Kem Dâu vừa ngon mắt vừa chiều vị giác bằng sự ngọt ngào. Bắt đầu bằng cái chạm môi với lớp kem whipping cream, cảm nhận ngay vị beo béo lẫn sốt dâu thơm lừng. ', 'Đang hoạt động', NULL, '2025-04-04 18:45:18');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(65, 'A300618', , 'Cà Phê Đen Nóng', 'Cà phê', 39000, 'Không ngọt ngào như Bạc sỉu hay Cà phê sữa, Cà phê đen mang trong mình phong vị trầm lắng, thi vị hơn. ', 'Đang hoạt động', NULL, '2025-04-05 15:26:52');
