(70, 'A300623', , 'Americano Tuyết Quất', 'Americano', 65000, 'Đá tuyết Quất thơm mát, kết hợp cùng Americano đắng nhẹ. Uống là mê! *Khuấy đều để thưởng thức trọn vị', 'Đang hoạt động', NULL, '2025-04-05 15:33:45');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(71, 'A300624', , 'Ô Long Tứ Quý Sen (Nóng)', 'Trà trái cây', 59000, 'Nền trà oolong hảo hạng kết hợp cùng hạt sen tươi, bùi bùi thơm ngon. Trà hạt sen là thức uống thanh mát, nhẹ nhàng phù hợp cho cả buổi sáng và chiều tối.', 'Đang hoạt động', NULL, '2025-04-05 16:24:50');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(72, 'A300625', , 'Ô Long Tứ Quý Sen', 'Trà trái cây', 49000, 'Nền trà oolong hảo hạng kết hợp cùng hạt sen tươi, bùi bùi và lớp foam cheese béo ngậy. Trà hạt sen là thức uống thanh mát, nhẹ nhàng phù hợp cho cả buổi sáng và chiều tối.', 'Đang hoạt động', NULL, '2025-04-05 15:37:09');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(73, 'A300626', , 'Ô Long Tứ Quý Kim Quất', 'Trà trái cây', 49000, 'Đậm hương trà, sảng khoái du xuân cùng Oolong Tứ Quý Kim Quất Trân Châu. Vị nước cốt kim quất tươi chua ngọt, thêm trân châu giòn dai.', 'Đang hoạt động', NULL, '2025-04-05 15:38:25');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(74, 'A300627', , 'Ô Long Tứ Quý Vải', 'Trà trái cây', 49000, 'Đậm hương trà, thanh mát sắc xuân với Oolong Tứ Quý Vải. Cảm nhận hương hoa đầu mùa, hòa quyện cùng vị vải chín mọng căng tràn sức sống.', 'Đang hoạt động', NULL, '2025-04-05 15:39:15');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(75, 'A300628', , 'Đào Kombucha', 'Trà trái cây', 59000, 'Trà hoa Hibiscus 0% caffeine chua nhẹ, kết hợp cùng trà lên men Kombucha hoàn toàn tự nhiên và Đào thanh mát tạo nên Hi-Tea Đào Kombucha chua ngọt cực cuốn. ', 'Đang hoạt động', NULL, '2025-04-05 16:25:02');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(76, 'A300629', , 'Yuzu Kombucha', 'Trà trái cây', 59000, 'Trà hoa Hibiscus 0% caffeine thanh mát, hòa quyện cùng trà lên men Kombucha 100% tự nhiên và mứt Yuzu Marmalade (quýt Nhật) mang đến hương vị chua chua lạ miệng.', 'Đang hoạt động', NULL, '2025-04-05 16:21:08');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(77, 'A300630', '', 'Yuzu Trân Châu', 'Trà trái cây', 49000, 'Không chỉ nổi bật với sắc đỏ đặc trưng từ trà hoa Hibiscus, Hi-Tea Yuzu còn gây ấn tượng với topping Yuzu (quýt Nhật) lạ miệng, kết hợp cùng trân châu trắng dai giòn sần sật, nhai vui vui.', 'Đang hoạt động', NULL, '2025-04-05 15:56:11');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(78, 'A300631', , 'Trà Đào', 'Trà trái cây', 49000, 'Sự kết hợp ăn ý giữa Đào cùng trà hoa Hibiscus, tạo nên tổng thể hài hoà dễ gây “thương nhớ” cho team thích món thanh mát, có vị chua nhẹ.', 'Đang hoạt động', NULL, '2025-04-05 15:55:57');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(79, 'A300632', , 'Trà Sữa Nướng Sương Sáo', 'Trà sữa', 55000, 'Tận hưởng hương vị Oolong nướng đậm đà được Nhà rang kỹ càng, quyện cùng sữa thơm béo, càng thêm hấp dẫn với sương sáo thanh mát.', 'Đang hoạt động', NULL, '2025-04-05 15:58:15');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(80, 'A300633', , 'Trà Sữa Ô Long Sương Sáo', 'Trà sữa', 55000, 'Trà Oolong Tứ Quý ngạt ngào hoa cỏ mùa xuân, hòa quyện cùng sữa thơm mịn màng, sương sáo thanh mát. Đó là Lộc Yêu Yêu ngọt ngào mà Nhà gửi gắm đến bạn.', 'Đang hoạt động', NULL, '2025-04-05 16:00:03');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(81, 'A300634', , 'Hồng Trà Sữa Nóng', 'Trà sữa', 55000, 'Từng ngụm trà chuẩn gu ấm áp, đậm đà beo béo bởi lớp sữa tươi chân ái hoà quyện. ', 'Đang hoạt động', NULL, '2025-04-05 16:21:30');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(82, 'A300635', , 'Hồng Trà Sữa Trân Châu', 'Trà sữa', 55000, 'Thêm chút ngọt ngào cho ngày mới với hồng trà nguyên lá, sữa thơm ngậy được cân chỉnh với tỉ lệ hoàn hảo, cùng trân châu trắng dai giòn có sẵn để bạn tận hưởng từng ngụm trà sữa ngọt ngào thơm ngậy thiệt đã.', 'Đang hoạt động', NULL, '2025-04-05 16:02:12');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(83, 'A300636', , 'Trà Đen Macchiato', 'Trà sữa', 55000, 'Trà đen được ủ mới mỗi ngày, giữ nguyên được vị chát mạnh mẽ đặc trưng của lá trà, phủ bên trên là lớp Macchiato \"homemade\" bồng bềnh quyến rũ vị phô mai mặn mặn mà béo béo.', 'Đang hoạt động', NULL, '2025-04-05 16:03:13');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(84, 'A300637', , 'Trà Sữa Ô Long BLao', 'Trà sữa', 39000, 'Tận hưởng hương vị núi rừng mát lành lắng đọng trong từng ngụm Trà Sữa Oolong B’Lao của Nhà. ', 'Đang hoạt động', NULL, '2025-04-05 16:21:50');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(85, 'A300638', , 'Trà Xanh Latte (Nóng)', 'Trà xanh - Chocolate', 49000, 'Trà Xanh Latte (Nóng) là phiên bản rõ vị trà nhất. Nhấp một ngụm, bạn chạm ngay vị trà xanh Tây Bắc chát nhẹ hoà cùng sữa nguyên kem thơm béo, đọng lại hậu vị ngọt ngào, êm dịu.', 'Đang hoạt động', NULL, '2025-04-05 16:22:10');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(86, 'A300639', , 'Trà Xanh Latte Sữa Yến Mạch', 'Trà xanh - Chocolate', 55000, 'Vị matcha êm mượt nhờ kết hợp với sữa yến mạch. *Khuấy đều để thưởng trọn hương vị.', 'Đang hoạt động', NULL, '2025-04-05 16:07:49');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(87, 'A300640', , 'Trà Xanh Latte Đậm Vị', 'Trà xanh - Chocolate', 49000, 'Lựa chọn phù hợp cho ai thích matcha đậm nhưng ngại đắng. *Khuấy đều để thưởng trọn hương vị.', 'Đang hoạt động', NULL, '2025-04-05 16:08:46');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(88, 'A300641', , 'Trà Xanh Latte', 'Trà xanh - Chocolate', 45000, 'Best seller 2023 - rất phù hợp cho ai muốn nhập môn matcha. *Khuấy đều để thưởng trọn hương vị.', 'Đang hoạt động', NULL, '2025-04-05 16:09:45');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(89, 'A300641', , 'Trà Xanh Latte Sữa Yến Mạch (Nóng)', 'Trà xanh - Chocolate', 55000, 'Vị matcha êm mượt nhờ kết hợp với sữa yến mạch (ui da nóng quá). *Khuấy đều để thưởng trọn hương vị.', 'Đang hoạt động', NULL, '2025-04-05 16:10:33');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(90, 'A300642', , 'Chocolate Đá', 'Trà xanh - Chocolate', 55000, 'Bột chocolate nguyên chất hoà cùng sữa tươi béo ngậy, ấm nóng. Vị ngọt tự nhiên, không gắt cổ, để lại một chút đắng nhẹ, cay cay trên đầu lưỡi.', 'Đang hoạt động', NULL, '2025-04-05 16:11:33');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(91, 'A300643', , 'Chocolate Nóng', 'Trà xanh - Chocolate', 55000, 'Bột chocolate nguyên chất hoà cùng sữa tươi béo ngậy. Vị ngọt tự nhiên, không gắt cổ, để lại một chút đắng nhẹ, cay cay trên đầu lưỡi.', 'Đang hoạt động', NULL, '2025-04-05 16:13:11');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(92, 'A300644', , 'Frosty Choco Chip', 'Thức uống đá xay', 59000, 'Đá Xay Frosty Choco Chip, thử là đã! Lớp whipping cream bồng bềnh, beo béo lại có thêm bột sô cô la và sô cô la chip trên cùng. Gấp đôi vị ngon với sô cô la thật xay với đá sánh mịn, đậm đà đến tận ngụm cuối cùng.', 'Đang hoạt động', NULL, '2025-04-05 16:14:47');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(93, 'A300645', , 'Frosty Trà Xanh', 'Thức uống đá xay', 59000, 'Đá Xay Frosty Trà Xanh như lời mời mộc mạc, ghé thăm Tây Bắc vào những ngày tiết trời se lạnh, núi đèo mây phủ.', 'Đang hoạt động', NULL, '2025-04-05 16:22:38');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(94, 'A300646', , 'Frosty Cà Phê Đường Đen', 'Thức uống đá xay', 59000, 'Đá Xay Frosty Cà Phê Đường Đen mát lạnh, sảng khoái ngay từ ngụm đầu tiên nhờ sự kết hợp vượt chuẩn vị quen giữa Espresso đậm đà và Đường Đen ngọt thơm.', 'Đang hoạt động', NULL, '2025-04-05 16:22:48');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(95, 'A300647', , 'Frosty Caramel Arabica', 'Thức uống đá xay', 59000, 'Caramel ngọt thơm quyện cùng cà phê Arabica Cầu Đất đượm hương gỗ thông, hạt dẻ và nốt sô cô la đặc trưng tạo nên Đá Xay Frosty Caramel Arabica độc đáo chỉ có tại Nhà. ', 'Đang hoạt động', NULL, '2025-04-05 16:22:56');
INSERT INTO `products` (`productID`, `productCode`, `thumbnail`, `productName`, `typeProduct`, `price`, `description`, `status`, `bestSeller`, `date`) VALUES
(96, 'A300648', , 'Frosty Phin Gato', 'Thức uống đá xay', 55000, 'Đá Xay Frosty Phin-Gato là lựa chọn không thể bỏ lỡ cho tín đồ cà phê. Cà phê nguyên chất pha phin truyền thống, thơm đậm đà, đắng mượt mà, quyện cùng kem sữa béo ngậy và đá xay mát lạnh. ', 'Đang hoạt động', NULL, '2025-04-05 16:23:07');
